$ErrorActionPreference='Stop';$ProgressPreference='SilentlyContinue';$root='C:\JudasValidation';$out="$root\M78FollowupResults";$base='http://192.168.122.1:8872';function Upload($p){Invoke-WebRequest -UseBasicParsing "$base/$([IO.Path]::GetFileName($p))" -Method Post -InFile $p|Out-Null}
try{if((Get-PSDrive C).Free -lt 64MB){throw 'Small affected-build reserve not available'};Invoke-WebRequest -UseBasicParsing "$base/m78-spacecraft-contracts.zip" -OutFile "$out\spacecraft-contracts.zip";Expand-Archive -LiteralPath "$out\spacecraft-contracts.zip" -DestinationPath "$root\Source" -Force;Import-Module "$root\VS2022\Common7\Tools\Microsoft.VisualStudio.DevShell.dll";Enter-VsDevShell -VsInstallPath "$root\VS2022" -SkipAutomaticLocation -DevCmdArguments '-arch=x64 -host_arch=x64';$rows=@();$ErrorActionPreference='Continue'
foreach($name in @('spacecraft_control','spacecraft_flight')){& "$root\VS2022\MSBuild\Current\Bin\MSBuild.exe" "$root\Build\judas_${name}_tests.vcxproj" /p:Configuration=Release /p:Platform=x64 /p:BuildProjectReferences=false /m:1 /verbosity:minimal /nologo 2>&1|Tee-Object -FilePath "$out\m78-native-$name-build.log";$code=$LASTEXITCODE;Upload "$out\m78-native-$name-build.log";if($code -ne 0){throw 'Affected build failed'};$exe="$root\Build\Release\judas_${name}_tests.exe";$stdout="$out\native-$name.stdout.log";$stderr="$out\native-$name.stderr.log";$p=Start-Process -FilePath $exe -WorkingDirectory "$root\Source" -PassThru -RedirectStandardOutput $stdout -RedirectStandardError $stderr;[void]$p.Handle;if(!$p.WaitForExit(180000)){Stop-Process -Id $p.Id -Force;throw 'Owned affected test timed out'};$p.Refresh();$rows+=@{case=$name;exitCode=$p.ExitCode;sha256=(Get-FileHash $exe).Hash.ToLower();sourceSHA256=(Get-FileHash ("$root\Source\tests\"+(if($name -eq 'spacecraft_control'){'SpacecraftControlTests.cpp'}else{'SpacecraftFlightTests.cpp'}))).Hash.ToLower()};Upload $stdout;Upload $stderr}
@{rows=$rows;freeBytes=(Get-PSDrive C).Free}|ConvertTo-Json -Depth 4|Set-Content "$out\m78-native-spacecraft-contracts.json" -Encoding UTF8;Upload "$out\m78-native-spacecraft-contracts.json"
}catch{[string]$_.Exception.Message|Set-Content "$out\m78-native-spacecraft-error.txt";Upload "$out\m78-native-spacecraft-error.txt";exit 1}
